/**
 * ONetworkGraph3D.scene - 3D 力导向网络图实现 (lazy-loaded)。
 *
 * 自实现 force-directed layout (避免引入 3d-force-graph 增加 bundle)。
 * 算法: 节点间斥力 (Coulomb) + 边吸引 (Hook),迭代松弛。
 */
'use client';

import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { useEffect, useMemo, useRef, useState } from 'react';
import * as THREE from 'three';
import type { ONetworkGraph3DData } from './ONetworkGraph3D.types';

const GROUP_COLORS = [
  'oklch(0.7 0.2 200)',   // cyan
  'oklch(0.65 0.25 300)', // purple
  'oklch(0.75 0.3 30)',   // orange
  'oklch(0.72 0.2 145)',  // green
  'oklch(0.78 0.18 75)',  // amber
];

interface PhysicsNode {
  id: string;
  label: string;
  group: string;
  value: number;
  pos: THREE.Vector3;
  vel: THREE.Vector3;
}

interface PhysicsEdge {
  source: PhysicsNode;
  target: PhysicsNode;
  weight: number;
}

function initLayout(data: ONetworkGraph3DData): { nodes: PhysicsNode[]; edges: PhysicsEdge[] } {
  const map = new Map<string, PhysicsNode>();
  for (const n of data.nodes) {
    map.set(n.id, {
      id: n.id,
      label: n.label ?? n.id,
      group: n.group ?? 'default',
      value: n.value ?? 1,
      pos: new THREE.Vector3(
        (Math.random() - 0.5) * 3,
        (Math.random() - 0.5) * 3,
        (Math.random() - 0.5) * 3
      ),
      vel: new THREE.Vector3(),
    });
  }
  const edges: PhysicsEdge[] = [];
  for (const e of data.edges) {
    const s = map.get(e.source);
    const t = map.get(e.target);
    if (s && t) edges.push({ source: s, target: t, weight: e.weight ?? 1 });
  }
  return { nodes: Array.from(map.values()), edges };
}

function stepPhysics(nodes: PhysicsNode[], edges: PhysicsEdge[], dt: number) {
  const repulsion = 0.4;
  const springLen = 1.2;
  const springK = 0.05;
  const damping = 0.88;
  const centerPull = 0.005;

  // 节点间斥力 (O(n²),小图 OK)
  for (let i = 0; i < nodes.length; i++) {
    for (let j = i + 1; j < nodes.length; j++) {
      const a = nodes[i]!;
      const b = nodes[j]!;
      const diff = a.pos.clone().sub(b.pos);
      const dist = Math.max(diff.length(), 0.1);
      const force = repulsion / (dist * dist);
      const dir = diff.normalize().multiplyScalar(force);
      a.vel.add(dir);
      b.vel.sub(dir);
    }
  }

  // 边吸引
  for (const e of edges) {
    const diff = e.target.pos.clone().sub(e.source.pos);
    const dist = diff.length();
    const force = springK * (dist - springLen) * e.weight;
    const dir = diff.normalize().multiplyScalar(force);
    e.source.vel.add(dir);
    e.target.vel.sub(dir);
  }

  // 中心拉力 + damping + 应用速度
  for (const n of nodes) {
    n.vel.sub(n.pos.clone().multiplyScalar(centerPull));
    n.vel.multiplyScalar(damping);
    n.pos.add(n.vel.clone().multiplyScalar(dt * 60));
  }
}

function NetworkGraph({ data, onHover }: { data: ONetworkGraph3DData; onHover: (label: string | null) => void }) {
  const physicsRef = useRef(initLayout(data));
  const nodeRefs = useRef<Map<string, THREE.Mesh>>(new Map());
  const linesRef = useRef<THREE.LineSegments | null>(null);

  // 数据变化重建
  useEffect(() => {
    physicsRef.current = initLayout(data);
  }, [data]);

  // 颜色映射
  const groupColorMap = useMemo(() => {
    const groups = Array.from(new Set(data.nodes.map((n) => n.group ?? 'default')));
    const map = new Map<string, string>();
    groups.forEach((g, i) => map.set(g, GROUP_COLORS[i % GROUP_COLORS.length]!));
    return map;
  }, [data.nodes]);

  // 边几何 (动态更新)
  const edgeGeometry = useMemo(() => new THREE.BufferGeometry(), []);
  // 注:edgePositions 大小跟 physicsRef.current.edges 对齐,但 physicsRef 不能作为
  // useMemo 依赖(它是 mutable ref)。data.edges 是真正驱动的源数据。
  const edgesLen = data.edges.length;
  const edgePositions = useMemo(
    () => new Float32Array(edgesLen * 6),
    [edgesLen]
  );

  useEffect(() => {
    edgeGeometry.setAttribute('position', new THREE.BufferAttribute(edgePositions, 3));
  }, [edgeGeometry, edgePositions]);

  useFrame((_, delta) => {
    stepPhysics(physicsRef.current.nodes, physicsRef.current.edges, Math.min(delta, 0.05));

    for (const n of physicsRef.current.nodes) {
      const mesh = nodeRefs.current.get(n.id);
      if (mesh) mesh.position.copy(n.pos);
    }

    let idx = 0;
    for (const e of physicsRef.current.edges) {
      edgePositions[idx++] = e.source.pos.x;
      edgePositions[idx++] = e.source.pos.y;
      edgePositions[idx++] = e.source.pos.z;
      edgePositions[idx++] = e.target.pos.x;
      edgePositions[idx++] = e.target.pos.y;
      edgePositions[idx++] = e.target.pos.z;
    }
    if (linesRef.current) {
      const attr = linesRef.current.geometry.getAttribute('position') as THREE.BufferAttribute;
      attr.needsUpdate = true;
    }
  });

  return (
    <>
      {/* edges */}
      <lineSegments ref={linesRef}>
        <primitive object={edgeGeometry} attach="geometry" />
        <lineBasicMaterial color="oklch(0.5 0.05 240)" transparent opacity={0.4} />
      </lineSegments>

      {/* nodes */}
      {physicsRef.current.nodes.map((n) => {
        const r = 0.05 + Math.min(n.value / 50, 0.2);
        return (
          <mesh
            key={n.id}
            ref={(el) => {
              if (el) nodeRefs.current.set(n.id, el);
            }}
            onPointerOver={(e) => {
              e.stopPropagation();
              onHover(n.label);
            }}
            onPointerOut={() => onHover(null)}
          >
            <sphereGeometry args={[r, 16, 16]} />
            <meshBasicMaterial color={groupColorMap.get(n.group)} />
          </mesh>
        );
      })}
    </>
  );
}

export interface NetworkSceneProps {
  data: ONetworkGraph3DData;
  interactive: boolean;
}

export function NetworkScene({ data, interactive }: NetworkSceneProps) {
  const [hoverLabel, setHoverLabel] = useState<string | null>(null);
  return (
    <div className="relative w-full h-full @container">
      <Canvas camera={{ position: [0, 0, 5], fov: 50 }} dpr={[1, 2]}>
        <ambientLight intensity={0.6} />
        <pointLight position={[5, 5, 5]} intensity={0.8} />
        <NetworkGraph data={data} onHover={setHoverLabel} />
        {interactive ? (
          <OrbitControls enablePan={false} minDistance={2} maxDistance={15} />
        ) : null}
      </Canvas>
      {hoverLabel ? (
        <div className="absolute top-3 left-3 px-3 py-1.5 bg-popover/90 text-popover-foreground text-sm rounded-md border border-border backdrop-blur-sm pointer-events-none">
          {hoverLabel}
        </div>
      ) : null}
    </div>
  );
}

export default NetworkScene;
